    return /[a-zA-Z_]/.test(ch);
  }

  isDigit(ch) {
    return /[0-9]/.test(ch);
  }

  isAlphaNum(ch) {
    return this.isAlpha(ch) || this.isDigit(ch);
  }

  current() {
    return this.source[this.pos] || '\0';
  }

  peek(offset = 1) {
    return this.source[this.pos + offset] || '\0';
  }

  advance() {
    if (this.current() === '\n') {
      this.line++;
      this.col = 1;
    } else {
      this.col++;
    }
    this.pos++;
