      fields.push({ name: fieldName, type: fieldType });
    }

    this.expect('PUNCT', '}');
    return { type: 'StructDecl', name, fields };
  }

  parseFunctionDecl() {
    const name = this.current().value;
    this.expect('IDENT');
    this.expect('PUNCT', '(');
    const params = [];
    if (!this.match('PUNCT', ')')) {
      params.push(this.current().value);
      this.advance();
      while (this.match('PUNCT', ',')) {
        params.push(this.current().value);
        this.advance();
      }
      this.expect('PUNCT', ')');
    }
    const body = this.parseBlockStatement();
    return { type: 'FunctionDecl', name, params, body };
  }

  parseBlockStatement() {
    this.expect('PUNCT', '{');
    const statements = [];
    while (!this.match('PUNCT', '}')) {
      if (this.current().type === 'EOF') break;
      statements.push(this.parseStatement());
    }
    return { type: 'BlockStatement', body: statements };
  }

  parseLetDecl() {
    const name = this.current().value;
    this.advance();
    let init = null;
    if (this.match('OP', '=')) {
      init = this.parseExpression();
    }
    this.match('PUNCT', ';');
    return { type: 'LetDecl', name, init };
  }

  parseExprStatement() {
    const expr = this.parseExpression();
    this.match('PUNCT', ';');
    return { type: 'ExprStatement', expr };
  }

  parseExpression() {
    return this.parseCallExpression();
  }

  parseCallExpression() {
    let expr = this.parsePrimaryExpression();
    while (this.current().type === 'PUNCT' && this.current().value === '(') {
      this.advance();
      const args = [];
      if (this.current().value !== ')') {
        args.push(this.parseExpression());
        while (this.match('PUNCT', ',')) {
          args.push(this.parseExpression());
        }
      }
      this.expect('PUNCT', ')');
      expr = { type: 'CallExpr', callee: expr, arguments: args };
    }
    return expr;
  }

  parsePrimaryExpression() {
    const token = this.current();
    if (token.type === 'NUMBER') {
      this.advance();
      return { type: 'Literal', value: parseInt(token.value, 10), kind: 'number' };
    }
    if (token.type === 'STRING') {
      this.advance();
      return { type: 'Literal', value: token.value, kind: 'string' };
    }
    if (token.type === 'IDENT' || (token.type === 'KEYWORD' && ['println', 'print'].includes(token.value))) {
      const name = token.value;
      this.advance();
      return { type: 'Identifier', name };
    }
    if (this.match('PUNCT', '(')) {
      const expr = this.parseExpression();
      this.expect('PUNCT', ')');
      return expr;
    }
    throw new Error(`Unexpected token: ${token.type}:${token.value}`);
  }
}

