    };
    fs.writeFileSync('EXECUTION_PROOF.json', JSON.stringify(execReport, null, 2));

    console.log('\n📊 Execution proof saved to EXECUTION_PROOF.json');
    console.log('🎉 Stage 2 self-reproduction proof complete!');
