        console.log(`   }`);
      }

      // IR 생성
      const irGen = new IRGenerator();
      const irProgram = irGen.generateProgram(ast);

      // struct literal와 member access 찾기
      let structLiteralCount = 0;
      let memberAccessCount = 0;

      function countExpressions(node) {
        if (node.type === 'StructLiteral') structLiteralCount++;
        if (node.type === 'MemberExpr') memberAccessCount++;

        if (node.type === 'CallExpr') {
