            countExpressions(arg);
          }
        } else if (node.type === 'LetDecl' && node.init) {
          countExpressions(node.init);
        } else if (node.body && Array.isArray(node.body)) {
          for (const stmt of node.body) {
            countExpressions(stmt);
          }
        }
      }

      for (const func of Object.values(irProgram)) {
        if (Array.isArray(func)) {
          for (const instr of func) {
            // count from instructions (simplified)
          }
        }
      }

      // AST에서 직접 count
      function walkAST(node) {
        if (node.type === 'StructLiteral') structLiteralCount++;
        if (node.type === 'MemberExpr') memberAccessCount++;

        if (node.body && Array.isArray(node.body)) {
          for (const child of node.body) {
            walkAST(child);
          }
        }
        if (node.init) walkAST(node.init);
        if (node.value) walkAST(node.value);
        if (node.arguments && Array.isArray(node.arguments)) {
