      // 이항 연산자 찾기
      let binaryOps = 0;
      function countBinOps(node) {
        if (!node) return;
        if (node.type === 'BinaryExpr') binaryOps++;
        if (node.body && Array.isArray(node.body)) {
          for (const child of node.body) countBinOps(child);
        }
        if (node.init) countBinOps(node.init);
        if (node.left) countBinOps(node.left);
        if (node.right) countBinOps(node.right);
        if (node.arguments && Array.isArray(node.arguments)) {
          for (const arg of node.arguments) countBinOps(arg);
